// Read-only chain transport shared by the local game-data projections.
// Related calls use EIP-1898 block hashes. Numeric-block fallback is verified
// before a projection is returned; it never enters a permanent number-keyed cache.
import { AbiCoder, Interface, keccak256, toBeHex } from '../vendor/ethers-app.mjs';
import { CHAIN, CONTRACTS, VOLUME_WINDOW } from '../app/chain-config.js';
import { sharedReadProvider, registerReadCacheInvalidator } from '../app/read-provider.js';
import { loadSchema, SCHEMA_HASH } from './generated/index.js';

const coder = AbiCoder.defaultAbiCoder();
const multicall = new Interface(['function aggregate3((address target,bool allowFailure,bytes callData)[] calls) payable returns ((bool success,bytes returnData)[] returnData)']);
const MULTICALL = '0xca11bde05977b3631167028862be2a173976ca11';
const EXTSLOAD = '0x1e2eaeaf';
const interfaces = new Map();
const UINT256 = (1n << 256n) - 1n;
export const hex = value => toBeHex(BigInt(value));
export const wordHex = value => toBeHex(BigInt(value) & UINT256, 32);
export const mappingSlot = (slot, key, type = 'uint256') => BigInt(keccak256(coder.encode([type, 'uint256'], [key, slot])));
export const arraySlot = slot => BigInt(keccak256(wordHex(slot)));
export const logIndex = log => Number(log.logIndex ?? log.index ?? 0);
export const logKey = log => `${log.transactionHash}:${logIndex(log)}`;
export const compareLogs = (a, b) => Number(a.blockNumber) - Number(b.blockNumber)
  || Number(a.transactionIndex ?? 0) - Number(b.transactionIndex ?? 0) || logIndex(a) - logIndex(b);

export function checkAbort(signal) {
  if (!signal?.aborted) return;
  if (signal.reason instanceof Error) throw signal.reason;
  const error = new Error('Read cancelled'); error.name = 'AbortError'; throw error;
}

export class ChainDataError extends Error {
  constructor(message, code = 'CHAIN_DATA_UNAVAILABLE', details = {}) {
    super(message); this.name = 'ChainDataError'; this.code = code; Object.assign(this, details);
  }
}

export async function contractInterface(name) {
  if (!interfaces.has(name)) interfaces.set(name, new Interface((await loadSchema(name)).abi));
  return interfaces.get(name);
}

function unsupportedHash(error) {
  return /invalid (?:argument|params)|cannot unmarshal object|blockhash.*(?:unsupported|not supported)|expected.*(?:string|block number)/i
    .test([error?.message, error?.error?.message, error?.info?.error?.message].filter(Boolean).join(' '));
}
function rangeRefused(error) {
  return /range|too many|more than|limit exceeded|response.*(?:large|size)|query.*(?:size|limit)|-32005/i
    .test([error?.message, error?.error?.message, error?.info?.error?.message].filter(Boolean).join(' '));
}

class Lane {
  constructor(size) { this.size = size; this.active = 0; this.waiters = []; }
  async run(fn, signal) {
    checkAbort(signal);
    if (this.active >= this.size) await new Promise((resolve, reject) => {
      const waiter = { resolve, reject, signal, abort: null };
      waiter.abort = () => { const i = this.waiters.indexOf(waiter); if (i >= 0) this.waiters.splice(i, 1); reject(signal.reason ?? new ChainDataError('Read cancelled', 'ABORTED')); };
      signal?.addEventListener('abort', waiter.abort, { once: true }); this.waiters.push(waiter);
    });
    else this.active += 1;
    try { checkAbort(signal); return await fn(); }
    finally {
      const next = this.waiters.shift();
      if (next) { next.signal?.removeEventListener('abort', next.abort); next.resolve(); }
      else this.active -= 1;
    }
  }
}

export class ChainClient {
  constructor({ provider, contracts = CONTRACTS, chain = CHAIN, clock = VOLUME_WINDOW, validateDeployment = true } = {}) {
    this.provider = provider; this.contracts = contracts; this.chain = chain; this.clock = clock;
    this.validateDeployment = validateDeployment; this.head = null; this.headFlight = null;
    this.checkedChain = false; this.contexts = new Map(); this.logLane = new Lane(3); this.readLane = new Lane(3);
    this.headers = new Map(); this.logFlights = new Map(); this.hashBlocks = true;
  }
  assertConfigured() {
    if (this.validateDeployment && this.chain.readSchema !== SCHEMA_HASH) {
      throw new ChainDataError('The updated contract deployment has not been configured for this site.', 'DEPLOYMENT_NOT_READY');
    }
    if (!this.provider) throw new ChainDataError('No public RPC is configured.');
  }
  address(name) {
    const address = this.contracts[name];
    if (!/^0x[0-9a-f]{40}$/i.test(address ?? '') || /^0x0{40}$/i.test(address)) throw new ChainDataError(`Missing ${name} contract address.`, 'DEPLOYMENT_NOT_READY');
    return address.toLowerCase();
  }
  async rpc(method, params, signal) { checkAbort(signal); const result = await this.provider.send(method, params); checkAbort(signal); return result; }
  async header(tag = 'latest', signal) {
    const normalized = typeof tag === 'number' || typeof tag === 'bigint' ? hex(tag) : tag;
    const result = await this.rpc('eth_getBlockByNumber', [normalized, false], signal);
    if (!result?.hash) throw new ChainDataError(`Block ${normalized} is unavailable.`);
    return { ...result, number: Number(result.number), timestamp: Number(result.timestamp) };
  }
  async snapshot({ signal, fresh = false, blockTag = 'latest' } = {}) {
    this.assertConfigured(); checkAbort(signal);
    if (!this.checkedChain) {
      if (Number(await this.rpc('eth_chainId', [], signal)) !== Number(this.chain.id)) throw new ChainDataError('The RPC is connected to a different chain.', 'WRONG_CHAIN');
      this.checkedChain = true;
    }
    let block;
    if (blockTag === 'latest' && !fresh && this.head && Date.now() - this.head.fetchedAt < 1_000) block = this.head.block;
    else if (blockTag === 'latest') {
      if (!this.headFlight) this.headFlight = this.header('latest').then(value => {
        this.head = { block: value, fetchedAt: Date.now() }; return value;
      }).finally(() => { this.headFlight = null; });
      block = await this.headFlight;
    } else block = await this.header(blockTag, signal);
    checkAbort(signal);
    let context = this.contexts.get(block.hash);
    if (!context) {
      context = new ChainSnapshot(this, block); this.contexts.set(block.hash, context);
      while (this.contexts.size > 8) this.contexts.delete(this.contexts.keys().next().value);
    }
    return context;
  }
  clearRecent() { this.head = null; this.contexts.clear(); this.logFlights.clear(); }
  async atBlock(method, params, snapshot, signal) {
    if (this.hashBlocks) {
      try { return await this.rpc(method, [...params, { blockHash: snapshot.block.hash, requireCanonical: true }], signal); }
      catch (error) { if (!unsupportedHash(error)) throw error; this.hashBlocks = false; }
    }
    snapshot.needsVerification = true;
    return this.rpc(method, [...params, hex(snapshot.block.number)], signal);
  }
  async logs(filter, { fromBlock = this.chain.deployBlock, toBlock, signal, onPage, initialSpan = 100_000 } = {}) {
    this.assertConfigured(); checkAbort(signal);
    if (!Number.isSafeInteger(Number(fromBlock)) || Number(fromBlock) < 0) throw new ChainDataError('A log query needs a valid lower block bound.');
    const last = Number(toBlock ?? (await this.snapshot({ signal })).block.number);
    if (Number(fromBlock) > last) return [];
    const key = JSON.stringify([filter, Number(fromBlock), last]);
    // Callers with their own cancellation/progress keep independent scans; the
    // central resource broker coalesces the usual same-panel requests above us.
    if (!signal && !onPage && this.logFlights.has(key)) return this.logFlights.get(key);
    const scan = (async () => {
      const result = []; let cursor = Number(fromBlock); let span = initialSpan;
      while (cursor <= last) {
        checkAbort(signal); const end = Math.min(last, cursor + span - 1);
        let page;
        try {
          page = await this.logLane.run(() => this.rpc('eth_getLogs', [{ ...filter, fromBlock: hex(cursor), toBlock: hex(end) }], signal), signal);
          if (!Array.isArray(page)) throw new ChainDataError('RPC returned an invalid log response.');
          if (page.length >= 1_000) {
            if (end === cursor) throw new ChainDataError('This block may exceed the RPC log-result limit. Use a provider with a larger limit.', 'LOG_LIMIT');
            span = Math.max(1, Math.floor(span / 2)); continue;
          }
        } catch (error) {
          checkAbort(signal);
          if (end > cursor && rangeRefused(error)) { span = Math.max(1, Math.floor(span / 2)); continue; }
          throw error;
        }
        const normalized = page.filter(log => !log.removed).map(log => ({ ...log,
          blockNumber: Number(log.blockNumber), transactionIndex: Number(log.transactionIndex ?? 0),
          index: logIndex(log), logIndex: logIndex(log),
        }));
        if (onPage) await onPage(normalized, { fromBlock: cursor, toBlock: end });
        else result.push(...normalized);
        cursor = end + 1;
      }
      return [...new Map(result.map(log => [logKey(log), log])).values()].sort(compareLogs);
    })();
    if (!signal && !onPage) this.logFlights.set(key, scan);
    try { return await scan; } finally { if (this.logFlights.get(key) === scan) this.logFlights.delete(key); }
  }
  async events(name, eventName, filters = {}, options = {}) {
    const iface = await contractInterface(name); const fragment = iface.getEvent(eventName);
    const topics = iface.encodeFilterTopics(fragment, fragment.inputs.map(input => input.indexed ? filters[input.name] ?? null : null));
    const logs = await this.logs({ address: this.address(name), topics }, options);
    return logs.map(log => ({ ...log, name: eventName, args: iface.decodeEventLog(fragment, log.data, log.topics) }));
  }
  async receipt(hash, signal) {
    const receipt = await this.rpc('eth_getTransactionReceipt', [hash], signal);
    if (!receipt) throw new ChainDataError('A generation transaction receipt is unavailable.');
    return { ...receipt, blockNumber: Number(receipt.blockNumber), logs: receipt.logs.map(log => ({ ...log, blockNumber: Number(log.blockNumber), logIndex: logIndex(log), index: logIndex(log) })) };
  }
  async blockAtTime(timestamp, upper, signal) {
    if (timestamp > upper.timestamp) return upper.number + 1;
    let low = Number(this.chain.deployBlock); let high = upper.number;
    let lowTime = this.clock.anchor + this.clock.deployDayBoundary * this.clock.period;
    let highTime = upper.timestamp;
    while (low < high) {
      checkAbort(signal);
      // Interpolation lands close to a recent day boundary without downloading
      // dozens of old block headers. Clamp strictly inside the remaining range
      // so irregular block intervals still converge to the exact lower bound.
      const fraction = highTime > lowTime ? (timestamp - lowTime) / (highTime - lowTime) : 0.5;
      const mid = Math.min(high - 1, Math.max(low, low + Math.floor((high - low) * fraction)));
      // Headers are deliberately not persisted by number: reorgs can replace them.
      const block = mid === upper.number ? upper : await this.header(mid, signal);
      if (block.timestamp < timestamp) { low = mid + 1; lowTime = block.timestamp; }
      else { high = mid; highTime = block.timestamp; }
    }
    return low;
  }
  dayAt(timestamp) {
    const { anchor, period, deployDayBoundary } = this.clock;
    if (!Number.isFinite(deployDayBoundary)) throw new ChainDataError('Deployment day clock is not configured.', 'DEPLOYMENT_NOT_READY');
    return Math.max(1, Math.floor((Number(timestamp) - anchor) / period) - deployDayBoundary + 1);
  }
  async dayRange(day, snapshot, signal) {
    const n = Number(day); if (!Number.isSafeInteger(n) || n < 1) throw new ChainDataError('Invalid game day.');
    if (!snapshot.dayRanges) snapshot.dayRanges = new Map();
    if (snapshot.dayRanges.has(n)) { const range = await snapshot.dayRanges.get(n); checkAbort(signal); return range; }
    const pending = this.resolveDayRange(n, snapshot);
    snapshot.dayRanges.set(n, pending);
    try { const range = await pending; checkAbort(signal); return range; }
    catch (error) { snapshot.dayRanges.delete(n); throw error; }
  }
  async resolveDayRange(n, snapshot) {
    const { anchor, period, deployDayBoundary } = this.clock;
    const start = (deployDayBoundary + n - 1) * period + anchor;
    const [fromBlock, after] = await Promise.all([
      this.blockAtTime(start, snapshot.block),
      start + period > snapshot.block.timestamp ? Promise.resolve(snapshot.block.number + 1) : this.blockAtTime(start + period, snapshot.block),
    ]);
    return { fromBlock, toBlock: after - 1 };
  }
}

export class ChainSnapshot {
  constructor(client, block) { this.client = client; this.block = block; this.reads = new Map(); this.queue = []; this.scheduled = false; this.needsVerification = false; }
  async verify(signal) {
    checkAbort(signal);
    // Logs are necessarily queried by number on many public providers, even
    // when storage reads support EIP-1898. Verify every published projection.
    if ((await this.client.header(this.block.number, signal)).hash !== this.block.hash) {
      this.client.clearRecent(); throw new ChainDataError('The chain reorganized during this read. Please retry.', 'CHAIN_REORG');
    }
  }
  async call(name, method, args = []) {
    const iface = await contractInterface(name); const fragment = iface.getFunction(method);
    const data = iface.encodeFunctionData(fragment, args);
    const result = iface.decodeFunctionResult(fragment, await this.rawCall(this.client.address(name), data));
    return result.length === 1 ? result[0] : result;
  }
  rawCall(address, data) {
    const key = `${address}:${data}`;
    if (this.reads.has(key)) return this.reads.get(key);
    const promise = new Promise((resolve, reject) => { this.queue.push({ address, data, resolve, reject }); });
    this.reads.set(key, promise); promise.catch(() => { if (this.reads.get(key) === promise) this.reads.delete(key); });
    if (!this.scheduled) { this.scheduled = true; queueMicrotask(() => this.flush()); }
    return promise;
  }
  async sendSingles(batch) {
    await Promise.all(batch.map(job => this.client.readLane.run(() => this.client.atBlock('eth_call', [{ to: job.address, data: job.data }], this)).then(job.resolve, job.reject)));
  }
  async flush() {
    this.scheduled = false; const jobs = this.queue.splice(0);
    for (let offset = 0; offset < jobs.length; offset += 25) {
      const batch = jobs.slice(offset, offset + 25);
      try {
        if (batch.length === 1 || this.client.multicallUnavailable) {
          await this.sendSingles(batch);
          continue;
        }
        const data = multicall.encodeFunctionData('aggregate3', [batch.map(job => [job.address, true, job.data])]);
        const raw = await this.client.atBlock('eth_call', [{ to: MULTICALL, data }], this);
        if (raw === '0x') { this.client.multicallUnavailable = true; await this.sendSingles(batch); continue; }
        const [results] = multicall.decodeFunctionResult('aggregate3', raw);
        if (results.length !== batch.length) throw new ChainDataError('Invalid Multicall response.');
        batch.forEach((job, i) => results[i].success ? job.resolve(results[i].returnData)
          : job.reject(new ChainDataError('A contract read reverted.', 'CALL_REVERTED', { address: job.address, data: job.data })));
      } catch (error) { batch.forEach(job => job.reject(error)); }
    }
  }
  word(name, slot) {
    const address = this.client.address(name); const key = `slot:${address}:${slot}`;
    if (!this.reads.has(key)) {
      const promise = (name === 'GAME' || name === 'CRAPS'
        ? this.rawCall(address, EXTSLOAD + wordHex(slot).slice(2))
        : this.client.atBlock('eth_getStorageAt', [address, wordHex(slot)], this)).then(BigInt);
      this.reads.set(key, promise); promise.catch(() => { if (this.reads.get(key) === promise) this.reads.delete(key); });
    }
    return this.reads.get(key);
  }
  async location(name, label, path = []) {
    const schema = await loadSchema(name); const entry = schema.fields[label];
    if (!entry) throw new ChainDataError(`Unknown ${name} storage field ${label}.`);
    let slot = BigInt(entry.slot); let offset = entry.offset; let type = entry.type;
    for (const component of path) {
      const shape = schema.types[type];
      if (shape.encoding === 'mapping') {
        slot = mappingSlot(slot, component, schema.types[shape.key].label); offset = 0; type = shape.value;
      } else if (shape.members) {
        const member = shape.members.find(item => item.label === component);
        if (!member) throw new ChainDataError(`Unknown storage member ${component}.`);
        slot += BigInt(member.slot); offset = member.offset; type = member.type;
      } else if (shape.base) {
        if (component === 'length' && shape.encoding === 'dynamic_array') return { slot, offset: 0, shape: { label: 'uint256', bytes: 32 }, schema };
        const index = BigInt(component); if (index < 0n) throw new ChainDataError('Negative array index.');
        const base = schema.types[shape.base];
        if (shape.encoding === 'dynamic_array') {
          if (index >= await this.word(name, slot)) throw new ChainDataError('Storage array index is out of bounds.');
          slot = arraySlot(slot);
        } else {
          const length = Number(shape.label.match(/\[(\d+)\]$/)?.[1]);
          if (Number.isFinite(length) && index >= BigInt(length)) throw new ChainDataError('Storage array index is out of bounds.');
        }
        if (!base.members && base.bytes <= 32) { const perSlot = BigInt(Math.floor(32 / base.bytes)); slot += index / perSlot; offset = Number(index % perSlot) * base.bytes; }
        else { slot += index * BigInt(Math.ceil(base.bytes / 32)); offset = 0; }
        type = shape.base;
      } else throw new ChainDataError(`Cannot index ${shape.label}.`);
    }
    return { slot, offset, shape: schema.types[type], schema };
  }
  async field(name, label, ...path) {
    const location = await this.location(name, label, path);
    return this.decodeAt(name, location);
  }
  async decodeAt(name, { slot, offset, shape, schema }) {
    if (shape.members) return Object.fromEntries(await Promise.all(shape.members.map(async member => [member.label,
      await this.decodeAt(name, { slot: slot + BigInt(member.slot), offset: member.offset, shape: schema.types[member.type], schema }),
    ])));
    if (shape.encoding === 'mapping' || shape.base) throw new ChainDataError('Read an explicit mapping key or array element.');
    if (shape.encoding === 'bytes') throw new ChainDataError('Dynamic bytes need an explicit bounded reader.');
    const value = ((await this.word(name, slot)) >> BigInt(offset * 8)) & ((1n << BigInt(shape.bytes * 8)) - 1n);
    if (shape.label === 'bool') return value !== 0n;
    if (shape.label === 'address' || shape.label.startsWith('contract ')) return toBeHex(value, 20).toLowerCase();
    if (/^bytes\d+$/.test(shape.label)) return toBeHex(value, shape.bytes);
    if (/^int\d+$/.test(shape.label)) return BigInt.asIntN(shape.bytes * 8, value);
    return value;
  }
}

let sharedClient = null;
export function chainClient() {
  if (!sharedClient) sharedClient = new ChainClient({ provider: sharedReadProvider() });
  return sharedClient;
}
export function setChainClientForTests(client) { sharedClient = client; }
registerReadCacheInvalidator(() => sharedClient?.clearRecent());
